// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _lockTime, uint256 _am) public {
        // Restrict _lockTime and _am to reasonable ranges
        _lockTime = bound(_lockTime, 0, 1000000);
        _am = bound(_am, 0, 100 ether);
        // Fund the test contract so it can send value
        vm.deal(address(this), 10 ether);
        // Send some value to Put to create a balance
        c.Put{value: 1 ether}(_lockTime);
        // Save the initial MinSum before any initialization
        uint256 initialMinSum = c.MinSum();
        // Attempt to SetMinSum (will revert if !intitalized in original)
        // We don't call SetMinSum here because the bug allows it after init
        // Instead, drive to Collect
        // Advance time past unlock
        vm.warp(block.timestamp + _lockTime + 1);
        // Call Collect with _am <= balance
        uint256 balance = address(c).balance;
        if (_am > balance) _am = balance;
        if (_am > 0) {
            // The buggy contract will fail because MinSum is 0 and balance >= 0 is true
            // The original contract also fails because MinSum is 0 and balance >= 0 is true
            // To see difference: after Collect call, if intitalized is false, MinSum should be 0
            c.Collect(_am);
        }
        // Assert that MinSum remains unchanged from initial value (0) because Initialized was never called
        assertTrue(c.MinSum() == initialMinSum, "MinSum should remain 0 if not initialized");
    }
}

