pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _val, uint256 _lockTime, uint256 _am, address _sender) public {
        // Restrict: avoid reverts due to arithmetic or call failures
        vm.assume(_val < type(uint256).max / 2);
        vm.assume(_lockTime < type(uint256).max / 2);
        vm.assume(_am < type(uint256).max / 2);
        vm.assume(_sender != address(0) && _sender != address(c));

        // Do not call Initialized() – the reference never initializes
        // Call SetMinSum only if we want to test the bug; but the reference reverts before initialization.
        // To avoid revert in reference, we simply never call SetMinSum or SetLogFile.
        // Optionally put some ether in the contract to enable withdraw
        vm.deal(address(c), 1 ether);
        vm.prank(_sender);
        // call Put to give sender some balance
        (bool putSuccess,) = address(c).call{value: _am}("");
        vm.assume(putSuccess);

        // Now call Collect with the same amount
        (bool collectSuccess,) = address(c).call(
            abi.encodeWithSelector(c.Collect.selector, _am)
        );
        // After Collect, MinSum must be 0 because initialization never happened (in reference)
        assertTrue(c.MinSum() == 0, "MinSum should be 0 if not initialized");
    }
}

