pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _lockTime, uint256 _val, uint256 _am, address _sender) public {
        // Assume sender is non-zero and has enough ether
        vm.assume(_sender != address(0));
        vm.deal(_sender, 10 ether);

        // Optionally set MinSum to something, but leave intitalized false
        c.SetMinSum(1 ether);

        // Send some ether via Put to set a balance
        vm.prank(_sender);
        c.Put{value: 1 ether}(_lockTime);

        // Now call Collect; since intitalized is false, the condition in SetMinSum doesn't affect this call
        // But the buggy version would have already changed MinSum in SetMinSum (which was called before intialization)
        // The rule: after Collect, MinSum should be the initial value (0) because initialization never happened
        // But in the reference, SetMinSum succeeded because it requires NOT intitalized, so it set MinSum to 1 ether.
        // So the reference actually has MinSum = 1 ether after SetMinSum.
        // The rule must hold on the reference, so we need a different invariant.
        // Let's rethink: The bug is that SetMinSum condition is negated. In the reference, SetMinSum only works before intitalized.
        // In the mutated version, SetMinSum only works after intitalized.
        // The difference manifests after Collect: MinSum differs.
        // For the reference, after any sequence ending with Collect, if intitalized was never set to true, then MinSum should be whatever was set by SetMinSum (which is allowed before init).
        // Actually the reference allows SetMinSum only before init, so if we never call Initialized, SetMinSum works and sets MinSum.
        // The buggy version requires init before SetMinSum, so if we never call Initialized, SetMinSum reverts, leaving MinSum as 0.
        // So the invariant is: If we never call Initialized, then after any valid sequence ending with Collect, MinSum is 0 in the buggy version, but nonzero in the reference if SetMinSum was called.
        // That's not a rule satisfied by C for all inputs.
        // Let's try a different invariant: The value of MinSum is preserved by Collect (i.e., Collect does not change MinSum).
        // Indeed, Collect does not modify MinSum in either version. So MinSum before and after Collect is the same.
        // This holds for both reference and buggy version.
        // But the test must break on the mutant. The mutant differs only in SetMinSum.
        // Actually the difference is after Collect, the state MinSum differs. That must be because of something before Collect.
        // Since Collect doesn't change MinSum, the difference is already there before Collect.
        // So the invariant is: After any sequence of calls that ends with Collect (which doesn't change MinSum), the value of MinSum is consistent with the initialization status.
        // The simplest invariant: If intitalized() returns false, then MinSum is 0.
        // (Assuming SetMinSum can only be called before initialization in reference, so after SetMinSum, MinSum becomes nonzero, but then intitalized is false, so the invariant fails.)
        // Wait: In reference, SetMinSum works before init, so after SetMinSum, intitalized is false but MinSum is nonzero. So the invariant "if not intitalized then MinSum==0" fails on reference.
        // We need a rule that the reference satisfies. Let's look at the bug: The condition is negated. In reference, SetMinSum requires !intitalized. In mutant, it requires intitalized.
        // So the only way to change MinSum in reference is to call SetMinSum before initializing.
        // In mutant, the only way to change MinSum is to call SetMinSum after initializing.
        // So if we never call Initialized, in reference MinSum can be set to nonzero, in mutant it stays 0.
        // If we call Initialized first, then in reference SetMinSum reverts (so MinSum stays 0), in mutant SetMinSum works and sets MinSum to nonzero.
        // But the statement says: "after a call to Collect(...) completes, the value of state variable MinSum differs: P.MinSum() != M.MinSum()".
        // So the difference is observable after a Collect call. But Collect doesn't change MinSum. So the difference must arise from previous calls.
        // The invariant should be: The value of MinSum after Collect is equal to the value it had just before the last call in the sequence that changed it (either SetMinSum or Initialized).
        // Actually simpler: The rule could be: The value of MinSum is unchanged by calls to Put and Collect.
        // That holds for both, so not good.
        // Let's think differently: The mutant changes the condition in SetMinSum. So the invariant should involve SetMinSum.
        // The public entry is Collect, but the difference is in state MinSum after Collect.
        // A valid invariant for the reference but broken by the mutant: "After any sequence of calls that includes at most one call to SetMinSum and a subsequent call to Collect, if Initialized was never called, then MinSum equals the value passed to SetMinSum."
        // In reference: SetMinSum works (since not initialized), so MinSum = _val.
        // In mutant: SetMinSum reverts (since not initialized), so MinSum remains 0.
        // So this rule holds in reference (since SetMinSum succeeds) and fails in mutant (MinSum stays 0 != _val).
        // But we need to restrict that SetMinSum is called and succeeds. In the reference, it always succeeds if intitalized is false.
        // So we can just assume we call SetMinSum before calling Initialized, and then call Collect.
        // Let's construct the test accordingly.

        // We'll set up a scenario: call SetMinSum with a nonzero value, then call Collect, then assert MinSum equals that value.
        // This holds in reference because SetMinSum doesn't revert. In mutant, SetMinSum reverts, so MinSum stays 0, breaking the assertion.

        c.SetMinSum(_val);
        uint minSumBefore = c.MinSum();

        vm.prank(_sender);
        (bool success, ) = address(c).call{value: 0}(""); // fallback calls Put(0)

        // Now call Collect
        c.Collect(_am);

        uint minSumAfter = c.MinSum();

        assertTrue(minSumAfter == minSumBefore, "MinSum changed by Collect");
    }
}

