pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 am) public {
        // Restrict to non-zero amount to ensure meaningful transfer
        vm.assume(am > 0);

        // Set up the contract: initialize it and fund the sender
        c.SetMinSum(0); // This is intended to set MinSum; buggy version will not change it
        c.Initialized();
        // Fund the test contract to call Collect
        vm.deal(address(this), am);
        // Call Put to deposit (required to have balance)
        c.Put{value: am}(0);
        // Now call Collect; this may revert or succeed
        // We only care about the case where it succeeds
        // The rule: MinSum remains 0 after a successful Collect
        bool success = false;
        try c.Collect(am) { success = true; } catch { /* collect reverted */ }
        if (success) {
            // In the reference, MinSum has been set to 0 (by SetMinSum).
            // In the buggy version, MinSum stayed at its initial 0 (never changed).
            // So the rule trivial: MinSum == 0, but this is true both ways.
            // However, the bug is that in the reference MinSum is 0 (set) and in buggy it's 0 (not set).
            // That's not a difference observable here. So we need a different approach.
            // Since the bug is that SetMinSum was deleted, the only way to observe it is that
            // in the reference, MinSum can be non-zero if we call SetMinSum with a value before initialization,
            // but the buggy version cannot set it. However, the assertion must be a general rule.
            // The correct rule: after initialization, MinSum equals the last call to SetMinSum before init.
            // But we cannot call SetMinSum after init. So we set it before init, then observe after Collect.
            // The reference will have MinSum = _val; the buggy will have MinSum = 0.
            // So we check that MinSum equals the value we set.
        }
    }
}

