pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSumVal, uint256 lockTime, uint256 collectAmt, uint256 depositAmt) public {
        vm.assume(minSumVal > 0 && collectAmt <= type(uint256).max && depositAmt <= type(uint256).max);
        vm.assume(depositAmt >= 1 ether);

        // Setup: initialize and set minSum
        c.SetMinSum(minSumVal);
        c.Initialized();

        // Deposit funds
        vm.deal(address(this), depositAmt);
        (bool successDep, ) = address(c).call{value: depositAmt}("");
        require(successDep, "Deposit failed");

        // Collect
        uint256 expectedMinSum = minSumVal;
        (bool successCol, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmt));

        // Rule: after Collect, MinSum should still be the value from SetMinSum
        if (successCol) {
            assertTrue(c.MinSum() == expectedMinSum, "MinSum changed after Collect");
        } else {
            assertTrue(true); // If Collect reverts, no state change can violate the rule
        }
    }
}

