import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 am, uint256 lockTime, uint256 sentValue) public {
        // Bound inputs to reasonable ranges
        am = bound(am, 0, 100 ether);
        lockTime = bound(lockTime, 0, 365 days);
        sentValue = bound(sentValue, 0, 100 ether);

        // Precondition: SetMinSum to allow Collect to succeed
        c.SetMinSum(0);
        c.Initialized();

        // Ensure sender has enough balance
        vm.deal(address(this), sentValue);

        // Call Put to deposit, then Collect
        c.Put{value: sentValue}(lockTime);

        // Fast forward time to unlock
        vm.warp(block.timestamp + lockTime + 1);

        // Call Collect — the address of the LogFile should remain zero
        c.Collect(am);

        // The general rule: LogFile address is zero (since SetLogFile was never called)
        assertTrue(address(c.LogFile()) == address(0));
    }
}

