pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 am, uint256 lockTime, uint256 deposit) public {
        // Bound deposit and lockTime to realistic values
        vm.assume(deposit < 1e18);
        vm.assume(lockTime < 10000);
        // Set min sum to 0 so Collect can succeed
        c.SetMinSum(0);
        c.SetLogFile(address(0x123));
        c.Initialized();
        // Fund the contract and make a deposit via Put
        vm.deal(address(this), deposit);
        c.Put{value: deposit}(lockTime);
        // Try Collect with a valid amount (0 to deposit)
        uint256 amToCollect = bound(am, 0, deposit);
        // Wrap Collect in try/catch to handle reverts
        bool reverted;
        try c.Collect(amToCollect) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // The general rule: locked_ must be false after Collect returns (whether it reverted or not)
        // Since locked_ is private, we test indirectly: Initialized() is still callable without revert
        assertTrue(address(c).call(abi.encodeWithSignature("Initialized()")));
    }
}

