pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _lockTime, uint256 _am, address caller) public {
        // Restrict inputs: avoid overflow in Put, and ensure callers are distinct for testing
        vm.assume(_lockTime <= type(uint256).max - block.timestamp);
        vm.assume(caller != address(0));

        // Set up required state: intitalized must be false for Put to work
        vm.prank(caller);
        // Send some ether to the contract via Put to create a deposit
        uint256 deposit = _am + 1; // ensure balance >= _am after deposit
        vm.deal(caller, deposit);
        // call Put, then collect
        c.Put{value: deposit}(_lockTime);
        // Now call Initialized() before Collect
        bool before = c.Initialized();
        // Attempt Collect; it may revert if conditions not met, but the state change of Initialized is what we track
        // We call Collect, capturing whether it reverts
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, _am));
        // Read after state
        bool after = c.Initialized();
        // The invariant: Initialized() should never change due to Collect
        assertTrue(before == after, "Initialized changed after Collect");
    }
}

