pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 am, address sender) public {
        vm.assume(sender != address(0));
        vm.deal(sender, 1 ether);
        vm.prank(sender);
        c.Put(0); // fund the sender
        // To make Collect succeed, set MinSum to 0 and ensure time passes
        c.SetMinSum(0);
        vm.warp(block.timestamp + 1);
        // Call Collect with an amount that can be collected
        uint256 amt = bound(am, 1, 1 ether);
        vm.prank(sender);
        c.Collect(amt);
        // The rule: after Collect, Initialized should be false (since Initialized() sets it to false in buggy version)
        // But in the correct version, Initialized() sets it to true, so after Collect, it should be true.
        // Actually, we need a rule that fails on buggy version. Wait: In correct, Initialized() sets true, so after Collect, Initialized() returns true.
        // In buggy, Initialized() sets false, so after Collect, Initialized() returns false.
        // So the rule is: after calling Collect, Initialized() returns true.
        // This will pass on correct (true == true) and fail on buggy (false == true).
        assertTrue(c.Initialized());
    }
}

