pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint lockTime, uint collectAmt) public {
        vm.assume(sender != address(0));
        lockTime = bound(lockTime, 0, 1000000);
        collectAmt = bound(collectAmt, 0, 1 ether);

        vm.deal(sender, 1 ether);
        vm.prank(sender);
        c.Put{value: 0.5 ether}(lockTime);

        uint beforeUnlock = c.Acc(sender).unlockTime;
        vm.prank(sender);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmt));
        uint afterUnlock = c.Acc(sender).unlockTime;

        // The rule: after Collect, unlockTime never exceeds (block.timestamp + lockTime) from the last Put.
        // Since only Put changes unlockTime, and the reference only updates when new time > old unlockTime,
        // the reference ensures unlockTime <= block.timestamp + lockTime.
        // The buggy version uses >=, which always updates, so it could set unlockTime larger than needed.
        assertTrue(afterUnlock <= block.timestamp + lockTime);
    }
}

