pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 lockTime, uint256 putValue, uint256 collectAmt) public {
        vm.assume(caller != address(0));
        vm.assume(putValue > 0);
        vm.assume(collectAmt > 0 && collectAmt <= putValue);
        vm.deal(caller, putValue);
        c.SetMinSum(1);
        c.SetLogFile(address(0x1234));
        c.Initialized();

        vm.prank(caller);
        c.Put{value: putValue}(lockTime);

        (uint unlockBefore, uint balBefore) = c.Acc(caller);
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmt));

        (uint unlockAfter, uint balAfter) = c.Acc(caller);

        // Rule: If Collect succeeded and balance is still at least MinSum, then unlockTime must be > block.timestamp
        bool rule = true;
        if (success && balAfter >= 1) {
            rule = (unlockAfter > block.timestamp);
        }
        // If Collect failed, unlockTime should remain unchanged
        if (!success) {
            rule = (unlockAfter == unlockBefore);
        }
        assertTrue(rule);
    }
}

