pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 lockTime, uint256 depositAmount, uint256 collectAmount) public {
        // Bound inputs to reasonable ranges
        vm.assume(caller != address(0));
        lockTime = bound(lockTime, 0, 365 days);
        depositAmount = bound(depositAmount, 1, 1e24);
        collectAmount = bound(collectAmount, 1, depositAmount);

        // Setup: initialize contract and set small MinSum
        c.SetMinSum(0);
        c.Initialized();

        // First, Put(deposit) with lockTime
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Put{value: depositAmount}(lockTime);

        // Record the unlockTime after Put
        uint256 unlockTimeAfterPut = c.Acc(caller).unlockTime;

        // Now call Collect
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // Rule: If the Collect succeeded (no revert) and the balance decreased,
        // then unlockTime must be strictly greater than block.timestamp + lockTime
        uint256 balanceBefore = c.Acc(caller).balance;
        // Note: we can't know if call reverted from the bool because we used low-level call
        // Instead, check state: if balance decreased, Collect succeeded
        uint256 balanceAfter = c.Acc(caller).balance;

        if (balanceAfter < balanceBefore) {
            // Collect succeeded and reduced balance
            uint256 newUnlockTime = c.Acc(caller).unlockTime;
            assertTrue(newUnlockTime > block.timestamp + lockTime, "Unlock time should be strictly greater than timestamp + lockTime after successful Collect");
        }
    }
}

