        if (!collectOk) return;
        uint newUnlockTime = c.Acc(address(this)).unlockTime;
        // The invariant: unlockTime should never decrease after a Collect call
        assertTrue(newUnlockTime >= oldUnlockTime, "unlockTime decreased");
    }
}

