import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 _am, uint256 _lockTime, uint256 _initialFunding, uint256 _minSum) public {
        // Bound inputs to avoid overflow and ensure meaningful test
        _am = bound(_am, 0, 1e18);
        _lockTime = bound(_lockTime, 0, 365 days);
        _initialFunding = bound(_initialFunding, _am, 1e18); // ensure initial funding >= _am
        _minSum = bound(_minSum, 0, 1e18);

        // Setup: fund the test caller with ether and set contract parameters
        address user = address(0x1234);
        vm.deal(user, _initialFunding);
        vm.deal(address(c), 0);
        vm.prank(user);
        c.Put{value: _initialFunding}(_lockTime);

        // Set MinSum and initialize contract
        c.SetMinSum(_minSum);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Warp time to bypass unlock condition
        vm.warp(block.timestamp + _lockTime + 1);

        // Record balances before Collect
        uint256 userBalanceBefore = user.balance;
        uint256 contractBalanceBefore = address(c).balance;

        // Execute Collect
        vm.prank(user);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSelector(c.Collect.selector, _am));

        // After Collect: if conditions met and success, user's call value is transferred; otherwise no change
        bool conditionsMet = (_initialFunding >= _minSum && _initialFunding >= _am && block.timestamp > _lockTime);
        if (conditionsMet) {
            // In the reference, on success: user receives _am ether (their balance increases by _am)
            // In the mutant, value 0 is sent, so user receives 0 ether
            // The property: user balance should increase by exactly _am if call succeeded
            assertTrue(
                (success && user.balance == userBalanceBefore + _am) ||
                (!success && user.balance == userBalanceBefore)
            );
        } else {
            // No change expected
            assertTrue(user.balance == userBalanceBefore && address(c).balance == contractBalanceBefore);
        }
    }
}

